CREATE TABLE pgpol_1.t(id integer," X " boolean,private_catalog_attribute text);
INSERT INTO pgpol_1.t VALUES(7,true,NULL);
CREATE TABLE pgpol_1.other(id integer);
CREATE VIEW pgpol_1.v AS SELECT id FROM pgpol_1.t;
CREATE POLICY rd ON pgpol_1.t FOR SELECT USING (id>0);
CREATE POLICY wr ON pgpol_1.t FOR INSERT WITH CHECK (id>0);
CREATE POLICY upd ON pgpol_1.t FOR UPDATE USING (id>0) WITH CHECK (id>0);
CREATE POLICY rd ON pgpol_1.other FOR SELECT USING (true);
CREATE POLICY private_catalog_policy ON pgpol_1.t FOR SELECT USING (true);
CREATE SEQUENCE pgpol_1.guard START 7;
CREATE TABLE pgpol_1.receipt AS SELECT p.oid,p.polrelid,p.polname,p.polcmd,p.polroles,p.polqual::text AS qual,p.polwithcheck::text AS withcheck FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid WHERE c.relnamespace='pgpol_1'::regnamespace

